// Build brief: turns the form into a clean brief for the AI. Stops with a clear message
// if something is wrong (no AI call is made).
const f = $json;
const pick = (label) => String(f[label] ?? '').trim();

const LEVELS = {
  A2: { name: 'A2 Elementary', sentences: 'short sentences (at most 12 words), everyday words, simple present/past contexts (home, work, travel, food)' },
  B1: { name: 'B1 Intermediate', sentences: 'sentences of at most 16 words, common words, everyday and study contexts' },
  B2: { name: 'B2 Upper-Intermediate', sentences: 'sentences of at most 22 words, some academic and IELTS-like contexts (education, environment, technology, society)' },
  C1: { name: 'C1 Advanced', sentences: 'natural complex sentences, formal and academic register, contexts useful for IELTS Writing Task 2 and Speaking Part 3' },
};
const CHECK_ITEMS = { A2: 7, B1: 7, B2: 8, C1: 8 };

const level = pick('Level').toUpperCase();
if (!LEVELS[level]) throw new Error('Pick a level: A2, B1, B2 or C1.');

const topicLabel = pick('Topic');
if (!topicLabel) throw new Error('Write the topic, e.g. "Present perfect vs past simple".');
if (topicLabel.length > 80) throw new Error('The topic must be at most 80 characters.');

const slug = (s) => s.toLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g, '')
  .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
const topicKey = slug(pick('Topic key') || topicLabel).slice(0, 60).replace(/-+$/, '');
if (topicKey.length < 2) throw new Error('The topic key needs at least 2 letters or digits.');

const rule = pick('Rule to teach');
if (!rule) throw new Error('Write the one rule this lesson teaches.');

const no = Number(pick('Lesson no') || 1);
if (!Number.isInteger(no) || no < 1 || no > 99) throw new Error('Lesson no must be a whole number from 1 to 99.');

const id = `${level.toLowerCase()}-${topicKey}-${no}`.slice(0, 80);
const azerbaijani = pick('Azerbaijani help').toLowerCase() === 'yes';

return {
  json: {
    runId: id + '-' + Date.now(),
    id,
    level,
    levelName: LEVELS[level].name,
    language: LEVELS[level].sentences,
    topic: { key: topicKey, label: topicLabel },
    rule,
    lessonNo: no,
    notes: pick('Notes'),
    azerbaijani,
    practiceItems: 3,
    checkItems: CHECK_ITEMS[level],
    minutes: 20,
  },
};

// Code validators: checks Claude's lesson against Orbiko's lesson format (the same rules the
// server applies, lesson-format.md) and the brief. Output: valid, errors (sent back to Claude),
// warnings (FYI), the parsed lesson.
const brief = $('Build brief').first().json;
const raw = String($json.text ?? $json.output ?? '');
const errors = [];
const warnings = [];

const normalise = (s) => String(s ?? '').replace(/[’‘]/g, "'").trim().replace(/\s+/g, ' ')
  .replace(/[.!?,;\s]+$/, '').toLowerCase();
const words = (s) => { const n = normalise(s); return n ? n.split(' ') : []; };
const bag = (list) => list.slice().sort().join('\u0001');
const isText = (v) => typeof v === 'string' || (v && typeof v === 'object' && !Array.isArray(v));

// 1. Parse the JSON (also accepts it wrapped in ```json fences)
let lesson;
try {
  lesson = JSON.parse(raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, ''));
  if (!lesson || typeof lesson !== 'object' || Array.isArray(lesson)) throw new Error('not one JSON object');
} catch (e) {
  return { json: { valid: false, errors: ['The output is not one valid JSON object: ' + e.message], warnings, lesson: null, brief, raw } };
}

// A text: a string (English) or {en, az}. Only <b>, <i>, <br> allowed.
function text(value, field, max, required = true) {
  if (value === undefined || value === null) {
    if (required) errors.push(`${field}: write the English text.`);
    return;
  }
  if (!isText(value)) { errors.push(`${field}: must be a string or {"en": …, "az": …}.`); return; }
  const values = typeof value === 'string' ? { en: value } : value;
  if (!String(values.en ?? '').trim()) errors.push(`${field}: write the English text (en).`);
  for (const [lang, v] of Object.entries(values)) {
    if (typeof v !== 'string') { errors.push(`${field}.${lang}: must be a string.`); continue; }
    if (lang !== 'en' && !v.trim()) errors.push(`${field}.${lang}: this text is empty.`);
    if (v.length > max) errors.push(`${field}${lang === 'en' ? '' : '.' + lang}: use at most ${max} characters (now ${v.length}).`);
    const tags = (v.match(/<\/?([a-z0-9]+)[^>]*>/gi) || []).map((t) => t.replace(/[<\/>]/g, '').split(/\s/)[0].toLowerCase());
    const bad = tags.filter((t) => !['b', 'i', 'br'].includes(t));
    if (bad.length) errors.push(`${field}: only <b>, <i> and <br> are allowed (found <${bad[0]}>).`);
    if (/\*\*/.test(v)) errors.push(`${field}: no markdown; use <b> for bold.`);
  }
  if (brief.azerbaijani && typeof value === 'object' && value.az === undefined) {
    warnings.push(`${field}: no Azerbaijani text.`);
  }
}
function plain(value, field) {
  if (typeof value !== 'string' || !value.trim()) { errors.push(`${field}: give a plain text.`); return false; }
  if (/<[^>]+>/.test(value)) errors.push(`${field}: plain text only, no HTML.`);
  return true;
}
function count(list, min, max, field, what) {
  const n = Array.isArray(list) ? list.length : 0;
  if (!Array.isArray(list) && list !== undefined) errors.push(`${field}: must be a list.`);
  if (n < min || n > max) errors.push(`${field}: use ${min} to ${max} ${what} (now ${n}).`);
  return Array.isArray(list) ? list : [];
}

// 2. Lesson fields and the brief
if (lesson.id !== brief.id) errors.push(`id: must be "${brief.id}".`);
if (lesson.level !== brief.level) errors.push(`level: must be "${brief.level}".`);
if (!lesson.topic || lesson.topic.key !== brief.topic.key) errors.push(`topic.key: must be "${brief.topic.key}".`);
text(lesson.topic && lesson.topic.label, 'topic.label', 80);
text(lesson.title, 'title', 120);
text(lesson.goal, 'goal', 300);
if (lesson.minutes !== undefined && !(Number.isInteger(lesson.minutes) && lesson.minutes >= 5 && lesson.minutes <= 40)) {
  errors.push('minutes: a lesson takes 5 to 40 minutes.');
}
if (lesson.position !== undefined && lesson.position !== null) errors.push('position: leave it out (the admin decides on publish).');

// 3. Learn cards
count(lesson.learn, 3, 8, 'learn', 'learn cards').forEach((card, i) => {
  const f = `learn[${i}]`;
  if (!card || typeof card !== 'object') { errors.push(`${f}: must be an object.`); return; }
  if (typeof card.icon !== 'string' || !card.icon.trim() || card.icon.length > 8) errors.push(`${f}.icon: give one emoji.`);
  text(card.label, f + '.label', 80);
  text(card.heading, f + '.heading', 160);
  if (card.body !== undefined) text(card.body, f + '.body', 1000);
  if (card.tip !== undefined) text(card.tip, f + '.tip', 300);
  const steps = card.steps === undefined ? [] : count(card.steps, 1, 5, f + '.steps', 'steps');
  steps.forEach((s, k) => text(s, `${f}.steps[${k}]`, 300));
  const examples = card.examples === undefined ? [] : count(card.examples, 1, 4, f + '.examples', 'examples');
  examples.forEach((e, k) => {
    if (!e || typeof e.ok !== 'boolean') errors.push(`${f}.examples[${k}].ok: must be true or false.`);
    text(e && e.text, `${f}.examples[${k}].text`, 300);
  });
  if (card.body === undefined && !steps.length && !examples.length) errors.push(`${f}: a learn card needs a body, steps or examples.`);
});

// 4. Worked example
const w = lesson.worked;
if (!w || typeof w !== 'object') errors.push('worked: give the worked example.');
else {
  text(w.question, 'worked.question', 300);
  count(w.steps, 2, 5, 'worked.steps', 'steps').forEach((s, k) => text(s, `worked.steps[${k}]`, 300));
  plain(w.answer, 'worked.answer');
}

// 5. Items
const ids = new Set();
function items(list, name, prefix, min, max) {
  return count(list, min, max, name, name === 'check' ? 'check items' : 'practice items').map((item, i) => {
    const f = `${name}[${i}]`;
    if (!item || typeof item !== 'object') { errors.push(`${f}: must be an object.`); return null; }
    if (!new RegExp('^' + prefix + '[1-9][0-9]{0,2}$').test(String(item.id))) errors.push(`${f}.id: use ids like ${prefix}1, ${prefix}2, …`);
    else if (ids.has(item.id)) errors.push(`${f}.id: the id ${item.id} is used twice.`);
    ids.add(item.id);
    text(item.prompt, f + '.prompt', 300);
    text(item.explanation, f + '.explanation', 600);
    if (item.type === 'choose') {
      const options = count(item.options, 2, 4, f + '.options', 'options');
      options.forEach((o, k) => plain(o, `${f}.options[${k}]`));
      if (new Set(options.map((o) => String(o).trim().toLowerCase())).size !== options.length) errors.push(`${f}.options: two options are the same.`);
      if (!Number.isInteger(item.answer) || item.answer < 0 || item.answer >= options.length) errors.push(`${f}.answer: the index of the right option (0 = first).`);
      if (item.whys === undefined) warnings.push(`${f}: no whys.`);
      else {
        if (!Array.isArray(item.whys) || item.whys.length !== options.length) errors.push(`${f}.whys: give one why per option.`);
        else item.whys.forEach((why, k) => text(why, `${f}.whys[${k}]`, 300));
      }
    } else if (item.type === 'type' || item.type === 'fix') {
      if (item.type === 'type') {
        if (typeof item.sentence !== 'string' || (item.sentence.match(/___/g) || []).length !== 1) errors.push(`${f}.sentence: needs exactly one ___ gap.`);
        else if (/<[^>]+>/.test(item.sentence)) errors.push(`${f}.sentence: plain text only, no HTML.`);
      } else {
        plain(item.wrong, f + '.wrong');
      }
      const accept = count(item.accept, 1, 5, f + '.accept', 'accepted answers');
      accept.forEach((a, k) => plain(a, `${f}.accept[${k}]`));
      const norm = accept.map(normalise);
      if (new Set(norm).size !== norm.length) errors.push(`${f}.accept: two accepted answers are the same (ignoring case and end punctuation).`);
      if (item.type === 'type' && norm.some((a) => a.split(' ').length > 4)) errors.push(`${f}.accept: an accepted answer has more than 4 words.`);
      if (item.type === 'fix' && item.wrong && norm.includes(normalise(item.wrong))) errors.push(`${f}.accept: the wrong sentence can't be an accepted answer.`);
      if (item.show !== undefined && item.show !== null && !plain(item.show, f + '.show')) { /* reported */ }
    } else if (item.type === 'build') {
      const tiles = count(item.tiles, 2, 12, f + '.tiles', 'tiles');
      tiles.forEach((t, k) => plain(t, `${f}.tiles[${k}]`));
      if (plain(item.answer, f + '.answer')) {
        if (bag(words(tiles.join(' '))) !== bag(words(item.answer))) errors.push(`${f}.answer: must use exactly the tiles' words, each once.`);
        else if (normalise(tiles.join(' ')) === normalise(item.answer)) errors.push(`${f}.tiles: the tiles are already in answer order; mix them.`);
      }
    } else {
      errors.push(`${f}.type: must be choose, type, fix or build.`);
    }
    return item;
  }).filter(Boolean);
}
items(lesson.practice, 'practice', 'p', 2, 6);
const check = items(lesson.check, 'check', 'c', 5, 15);

// 6. A good mix in the check (the server needs 2 types; the brief asks for production)
const types = check.map((c) => c.type);
if (new Set(types).size < 2) errors.push('check: use at least two different item types.');
for (const [type, min] of [['choose', 2], ['type', 1], ['fix', 1], ['build', 1]]) {
  if (types.filter((t) => t === type).length < min) errors.push(`check: use at least ${min} "${type}" item${min > 1 ? 's' : ''}.`);
}
if (check.length !== brief.checkItems) warnings.push(`check: ${check.length} items (asked for ${brief.checkItems}).`);
const sentences = check.map((c) => normalise(c.sentence || c.wrong || c.answer && c.type === 'build' && c.answer || '')).filter(Boolean);
if (new Set(sentences).size !== sentences.length) errors.push('check: two items use the same sentence.');

return { json: { valid: errors.length === 0, errors, warnings, lesson, brief, raw } };

// Prepare retry: sends the brief back to Claude with the problems found. After 2 retries it stops.
const MAX_RETRIES = 2;
const v = $json;
const attempt = $runIndex + 1;

if (attempt > MAX_RETRIES) {
  throw new Error(`Gave up after ${MAX_RETRIES} retries: ` + v.errors.join(' | '));
}

return {
  json: {
    ...v.brief,
    retries: attempt,
    fix: { errors: v.errors, previous: v.raw },
  },
};

// Prepare solve: the lesson's items WITHOUT answers, whys or explanations, for a blind solve.
const lesson = $json.lesson;
const en = (t) => (t && typeof t === 'object' ? t.en : t) ?? '';
const strip = (s) => String(s).replace(/<br\s*\/?>/gi, ' ').replace(/<[^>]+>/g, '');

const sheet = [...lesson.practice, ...lesson.check].map((item) => {
  const q = { id: item.id, type: item.type, prompt: strip(en(item.prompt)) };
  if (item.type === 'choose') q.options = item.options;
  if (item.type === 'type') q.sentence = item.sentence;
  if (item.type === 'fix') q.wrong = item.wrong;
  if (item.type === 'build') q.tiles = item.tiles;
  return q;
});

return { json: { lesson: $json.lesson, brief: $json.brief, sheetJson: JSON.stringify(sheet, null, 2) } };

// Compare: the blind solver's answers against the lesson's keys. Flags an item when the solver
// got another answer, found a second correct answer that isn't accepted, or saw a problem.
const v = $('Prepare solve').first().json;
const lesson = v.lesson;
const raw = String($json.text ?? $json.output ?? '');
const normalise = (s) => String(s ?? '').replace(/[’‘]/g, "'").trim().replace(/\s+/g, ' ')
  .replace(/[.!?,;\s]+$/, '').toLowerCase();

let solved;
try {
  solved = JSON.parse(raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '')).answers;
  if (!Array.isArray(solved)) throw new Error('no "answers" list');
} catch (e) {
  throw new Error('The blind solver did not return valid JSON: ' + e.message + '. Run the workflow again.');
}
const byId = new Map(solved.map((a) => [a.id, a]));

const flagged = [];
for (const item of [...lesson.practice, ...lesson.check]) {
  const a = byId.get(item.id);
  const problems = [];
  let key;
  let ok;
  if (item.type === 'choose') {
    key = [item.options[item.answer]];
    ok = (x) => normalise(x) === normalise(item.options[item.answer]);
  } else if (item.type === 'build') {
    key = [item.answer];
    ok = (x) => normalise(x) === normalise(item.answer);
  } else {
    key = item.accept;
    ok = (x) => item.accept.some((acc) => normalise(acc) === normalise(x));
  }
  if (!a) problems.push('The solver skipped this item.');
  else {
    if (!ok(a.answer)) problems.push(`A careful solver answered “${a.answer}”.`);
    const others = (Array.isArray(a.otherCorrect) ? a.otherCorrect : []).filter((x) => !ok(x));
    if (others.length) problems.push(`The solver says these are also correct: ${others.map((x) => '“' + x + '”').join(', ')}.`);
    if (a.problem && String(a.problem).trim()) problems.push('Solver note: ' + String(a.problem).trim());
  }
  if (problems.length) flagged.push({ id: item.id, type: item.type, key, problems });
}

return { json: { ok: flagged.length === 0, flagged, lesson, brief: v.brief } };

// Prepare fix: sends only the flagged items back to Claude. After 2 fixes it stops the flow.
const MAX_FIXES = 2;
const v = $json;
const attempt = $runIndex + 1;

const list = v.flagged.map((f) =>
  `${f.id} (${f.type})\n  Your key: ${f.key.join(' / ')}\n  Problem: ${f.problems.join(' ')}`).join('\n\n');

if (attempt > MAX_FIXES) {
  throw new Error(`Still flagged after ${MAX_FIXES} fixes: ` + list.replace(/\n\s*/g, ' ') + ' || Run the workflow again or fix it in Admin → Grammar.');
}

return {
  json: {
    brief: v.brief,
    lessonJson: JSON.stringify(v.lesson, null, 2),
    flaggedText: list,
    fixAttempt: attempt,
  },
};

