// Build Orbiko JSON: the checked lesson as the body for POST /api/v1/admin/grammar/lessons.
// It arrives in Admin → Grammar as a DRAFT; the admin publishes it.
const lesson = { ...$json.lesson };
delete lesson.position;
if (!lesson.minutes) lesson.minutes = $json.brief.minutes;
return { json: { lesson, brief: $json.brief } };

// Report Orbiko error: stops the flow with Orbiko's answer (every problem with its JSON path).
const r = $json;
const body = r.body || {};
const details = Array.isArray(body.errors) && body.errors.length
  ? body.errors.map((e) => `${e.field}: ${e.message}`).join(' | ')
  : (body.detail || JSON.stringify(body).slice(0, 500));
const hint = r.statusCode === 409 ? ' (a lesson with this id exists: use another "Lesson no")'
  : r.statusCode === 401 || r.statusCode === 403 ? ' (check email/password in "Orbiko settings")' : '';
throw new Error(`Orbiko answered ${r.statusCode}: ${details}${hint}`);
